using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Reflection;
using System.Text;
using System.Windows;
using System.Windows.Interop;
using System.Windows.Media;
using System.Windows.Media.Imaging;
using System.Windows.Threading;

namespace DeskBloom {
  internal static class Tests {
    private static void Assert(bool value,string message){if(!value)throw new Exception(message);}
    private static IEnumerable<T> Descendants<T>(DependencyObject root) where T:DependencyObject {for(int i=0;i<VisualTreeHelper.GetChildrenCount(root);i++){var child=VisualTreeHelper.GetChild(root,i);var match=child as T;if(match!=null)yield return match;foreach(var nested in Descendants<T>(child))yield return nested;}}
    private static void Pump(int milliseconds){var frame=new DispatcherFrame();var timer=new DispatcherTimer {Interval=TimeSpan.FromMilliseconds(milliseconds)};timer.Tick+=delegate {timer.Stop();frame.Continue=false;};timer.Start();Dispatcher.PushFrame(frame);}
    internal static int Run(string directory){Directory.CreateDirectory(directory);var log=new List<string>();MainWindow main=null;try{
      string root=Path.Combine(directory,"migration-"+Guid.NewGuid().ToString("N")),dataRoot=Path.Combine(root,"Data"),desktop=Path.Combine(root,"Desktop"),groupsRoot=Path.Combine(root,"Groups"),downloads=Path.Combine(root,"Downloads"),first=Path.Combine(root,"Рабочий стол 1"),second=Path.Combine(root,"Рабочий стол 2");foreach(string path in new[]{dataRoot,desktop,groupsRoot,downloads,first,second})Directory.CreateDirectory(path);
      string container=Path.Combine(first,"Группы");Directory.CreateDirectory(container);File.WriteAllText(Path.Combine(container,".deskbloom-groups"),"DeskBloom.Groups/1");var one=new GroupData {Name="Учёба",FolderPath=Path.Combine(container,"Учёба"),X=620,Y=124,Open=false};var two=new GroupData {Name="Скачанное",FolderPath=Path.Combine(downloads,"Скачанное"),X=400,Y=320,Open=true};var three=new GroupData {Name="Учёба",FolderPath=Path.Combine(dataRoot,"Files",Guid.NewGuid().ToString("N")),X=60,Y=84};foreach(var group in new[]{one,two,three}){Directory.CreateDirectory(group.FolderPath);File.WriteAllText(Path.Combine(group.FolderPath,"содержимое.txt"),group.Id);Json.Write(PortableLayouts.DocumentPath(group),new GroupDocument {Group=group});}
      var old=new StateData {Version=1,Groups=null,LegacyPages=new List<LegacyPage>{new LegacyPage {Id=Guid.NewGuid().ToString("N"),StorageFolder=first,Groups=new List<GroupData>{one}},new LegacyPage {Id=Guid.NewGuid().ToString("N"),StorageFolder=second,Groups=new List<GroupData>{two,three}}},LegacyPage=1};Json.Write(Path.Combine(dataRoot,"state.json"),old);File.WriteAllText(Path.Combine(desktop,"same.txt"),"Active desktop");File.WriteAllText(Path.Combine(first,"same.txt"),"Former page one");File.WriteAllText(Path.Combine(second,"same.txt"),"Former page two");File.WriteAllText(Path.Combine(first,"Основная.desk"),"{\"Format\":\"DeskBloom.Desktop\"}");string shots=Path.Combine(dataRoot,"Screenshots");Directory.CreateDirectory(shots);File.WriteAllBytes(Path.Combine(shots,"saved.png"),new byte[]{1,2,3,4});
      var store=new Store(dataRoot,groupsRoot,desktop);Assert(store.State.Groups.Count==3,"read legacy groups");Assert(Migration.Run(store).Count==0,"complete migration");Assert(store.State.LegacyPages==null&&store.State.Migrated,"remove runtime pages");Assert(store.State.Groups.Select(g=>g.Id).Distinct().Count()==3,"unique stable group IDs");Assert(one.Id==store.State.Groups[0].Id&&store.State.Groups[0].X==620&&!store.State.Groups[0].Open,"preserve coordinates and open state");foreach(var group in store.State.Groups)Assert(File.ReadAllText(Path.Combine(group.FolderPath,"содержимое.txt"))==group.Id,"group file integrity");Assert(store.State.Groups.Single(g=>g.Id==two.Id).FolderPath==two.FolderPath,"keep external Downloads folder");Assert(Directory.GetFiles(desktop,"same*.txt").Select(File.ReadAllText).OrderBy(s=>s).SequenceEqual(new[]{"Active desktop","Former page one","Former page two"}.OrderBy(s=>s)),"merge old desktop files without overwrite");Assert(!Directory.Exists(Path.Combine(desktop,"Группы"))&&Directory.GetFiles(desktop,"*.desk").Length==0,"do not create native group icons or desk files");
      log.Add("PASS: legacy pages merge into one group list with stable IDs, file contents, coordinates and open state; ordinary page files return to the native desktop without overwriting collisions; Downloads groups stay in Downloads.");
      var loaded=new Store(dataRoot,groupsRoot,desktop);Assert(loaded.State.Groups.Count==3&&Migration.Run(loaded).Count==0,"idempotent reload");string name=Path.Combine(root,"вход.txt");File.WriteAllText(name,"Moved");string moved=loaded.MoveIn(name,loaded.State.Groups[0]);Assert(!File.Exists(name)&&File.ReadAllText(moved)=="Moved","physical file move");File.WriteAllText(name,"Second");string movedAgain=loaded.MoveIn(name,loaded.State.Groups[0]);Assert(movedAgain!=moved&&File.ReadAllText(moved)=="Moved","no overwrite");string nested=Path.Combine(root,"Проект");Directory.CreateDirectory(nested);File.WriteAllText(Path.Combine(nested,"вложенный.txt"),"Nested");Assert(File.ReadAllText(Path.Combine(loaded.MoveIn(nested,loaded.State.Groups[0]),"вложенный.txt"))=="Nested","whole folders");
      string marker=PortableLayouts.DocumentPath(loaded.State.Groups[0]);PortableLayouts.Import(loaded,marker);Assert(loaded.State.Groups.Count==3,"idempotent .groups opening");var removed=loaded.State.Groups[0];PortableLayouts.Detach(loaded,removed);loaded=new Store(dataRoot,groupsRoot,desktop);Assert(loaded.State.Groups.Count==2,"do not revive removed groups");PortableLayouts.Import(loaded,marker);Assert(loaded.State.Groups.Count==3&&File.ReadAllText(moved)=="Moved","restore group from document");Migration.MoveGroup(loaded,loaded.State.Groups.Single(g=>g.Id==one.Id),groupsRoot,"Новое имя");Assert(Directory.Exists(Path.Combine(groupsRoot,"Новое имя")),"physical group rename");
      File.Delete(loaded.StatePath);if(File.Exists(loaded.StatePath+".bak"))File.Delete(loaded.StatePath+".bak");loaded=new Store(dataRoot,groupsRoot,desktop);Assert(loaded.State.Groups.Count==3,"recover only from group documents");loaded.Save();log.Add("PASS: physical file/folder moves, duplicate names, renaming, .groups reopening, explicit removal/restoration and recovery without state.json preserve all contents.");
      var groupForCrash=loaded.State.Groups.First(g=>Path.GetDirectoryName(g.FolderPath)==groupsRoot);string crashSource=groupForCrash.FolderPath,crashDestination=Path.Combine(groupsRoot,"После сбоя");Json.Write(Path.Combine(dataRoot,"group-folder-move.json"),new FolderMove {GroupId=groupForCrash.Id,Source=crashSource,Destination=crashDestination,Name="После сбоя"});Directory.Move(crashSource,crashDestination);Migration.Recover(loaded);Assert(loaded.GroupPath(groupForCrash)==crashDestination&&File.ReadAllText(Path.Combine(crashDestination,"содержимое.txt"))==groupForCrash.Id,"recover interrupted directory move");log.Add("PASS: a group directory moved before configuration was saved is recovered from the durable journal.");
      var app=new Application {ShutdownMode=ShutdownMode.OnExplicitShutdown};bool icons=Win.IsWindowVisible(Win.IconView());main=new MainWindow(loaded){Quiet=true};main.Show();Pump(350);Assert(main.GroupWindows.Count()==loaded.State.Groups.Count,"only group windows; no pagination");Assert(!main.IsVisible&&main.GroupWindows.All(w=>w.IsVisible),"desktop panels and hidden controller");foreach(var window in main.GroupWindows)Assert((Win.GetWindowLong(new WindowInteropHelper(window).Handle,-16)&0x40000000)==0,"desktop-owned top-level windows");var card=main.Cards.First();bool original=card.Data.Open;card.Toggle();Pump(250);Assert(card.Data.Open!=original,"inline group toggle");card.Toggle();Pump(250);Ui.Render((System.Windows.FrameworkElement)main.GroupWindows.First().Content,Path.Combine(directory,"group-preview.png"));
      var groupNames=loaded.State.Groups.ToDictionary(g=>g.Id,g=>g.Name);var groupPaths=loaded.State.Groups.ToDictionary(g=>g.Id,g=>g.FolderPath);main.ChangeLanguage("en");Pump(100);Assert(L.T("Создать группу")=="Create group"&&L.Items(1)=="1 item"&&L.Items(2)=="2 items","English labels and item counts");using(var englishMenu=main.BuildTrayMenu()){Assert(englishMenu.Items[0].Text=="Create group"&&englishMenu.Items[englishMenu.Items.Count-1].Text=="Exit","English tray commands");var languageMenu=englishMenu.Items.Cast<System.Windows.Forms.ToolStripItem>().OfType<System.Windows.Forms.ToolStripMenuItem>().Single(item=>item.Text=="Язык / Language");Assert(((System.Windows.Forms.ToolStripMenuItem)languageMenu.DropDownItems[1]).Checked,"English language menu state");}Assert(new Store(dataRoot,groupsRoot,desktop).State.Language=="en","language persists after reloading state");Assert(loaded.State.Groups.All(g=>g.Name==groupNames[g.Id]&&g.FolderPath==groupPaths[g.Id]),"language switch never renames or moves user groups");var englishButtons=Descendants<System.Windows.Controls.Button>(main.Cards[0]).Select(b=>System.Windows.Automation.AutomationProperties.GetName(b)).ToList();Assert(englishButtons.Contains("+ Files")&&englishButtons.Contains("+ Folder"),"English group controls");main.ChangeLanguage("ru");Pump(100);using(var russianMenu=main.BuildTrayMenu())Assert(russianMenu.Items[0].Text=="Создать группу","Russian restored immediately");Assert(new Store(dataRoot,groupsRoot,desktop).State.Language=="ru","Russian selection persists");log.Add("PASS: switching Russian/English updates group controls and tray menus immediately, persists after reload, uses correct English item counts, and never changes user group names or file paths.");
      Assert(!Assembly.GetExecutingAssembly().GetTypes().Any(t=>t.Name=="ShotBadge"||t.Name=="NativeDesktopPages"||t.Name=="DesktopIconPositions"),"removed feature implementations");Assert(!typeof(Win).GetMethods(BindingFlags.Static|BindingFlags.NonPublic).Any(m=>m.Name.Contains("Clipboard")),"no clipboard listener APIs");var oldClipboard=Clipboard.GetDataObject();try{var pixels=new byte[16*16*4];var bitmap=BitmapSource.Create(16,16,96,96,PixelFormats.Bgra32,null,pixels,64);Clipboard.SetImage(bitmap);Pump(300);Assert(Directory.GetFiles(shots).Length==1&&File.ReadAllBytes(Path.Combine(shots,"saved.png")).SequenceEqual(new byte[]{1,2,3,4}),"clipboard images are ignored and old screenshots preserved");}finally{if(oldClipboard!=null)try{Clipboard.SetDataObject(oldClipboard,true);}catch{}}
      string[] received=null;string token="groups-test-"+Guid.NewGuid().ToString("N"),queueRoot=Path.Combine(root,"Queue");Assert(RequestQueue.Enqueue(queueRoot,token,new List<string>{"@new-group"}),"early request accepted");using(var queue=new RequestQueue(queueRoot,token,main,delegate(string[] paths){received=paths;})){Pump(200);Assert(received!=null&&received.Single()=="@new-group","early queue delivery");}ToggleTests.Run(main,directory,log);AppearanceTests.Run(main,directory,log);OptimizationTests.Run(main,directory,log);main=null;Pump(100);Assert(Win.IsWindowVisible(Win.IconView())==icons,"native icon visibility unchanged");app.Shutdown();log.Add("PASS: only group panels are created; expansion works; native desktop icons stay intact; page and screenshot classes/listeners are absent; clipboard images create no files; previous screenshots remain untouched; cold-start requests are delivered.");
      File.WriteAllLines(Path.Combine(directory,"test-results.txt"),log,Encoding.UTF8);return 0;
    }catch(Exception e){log.Add("FAIL: "+e);File.WriteAllLines(Path.Combine(directory,"test-results.txt"),log,Encoding.UTF8);if(main!=null)main.Close();return 1;}}
  }
}
